"use client";

import { Suspense } from "react";
import { useState, useRef } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { signOut } from "next-auth/react";
import { useAvatar } from "@/context/AvatarContext";
import { useAuthMe } from "@/hooks/useUserData";
import { clearAuthStorage } from "@/lib/auth";
import UpgradeModal from "./layout/UpgradeModal";

interface DashboardNavbarProps {
  pageTitle: string;
  pageIcon: React.ReactNode;
  actionSlot?: React.ReactNode;
}

function UpgradeModalGate() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const pathname = usePathname();

  const isOpen = searchParams.get("upgrade") === "true";

  const handleClose = () => {
    const params = new URLSearchParams(searchParams.toString());
    params.delete("upgrade");
    router.push(`${pathname}?${params.toString()}`);
  };

  return (
    <UpgradeModal isOpen={isOpen} onClose={handleClose} onUpgrade={() => {}} />
  );
}

