export default function DashboardNavbar({
  pageTitle,
  pageIcon,
  actionSlot,
}: DashboardNavbarProps) {
  const { avatarUrl } = useAvatar();
  const { data: authData } = useAuthMe();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);
  const router = useRouter();
  const pathname = usePathname();

  // In Progress
  // In Progress
  const subcriptionPlanName = "Basi";

  const openUpgradeModal = () => {
    router.push("?upgrade=true");
  };

  const handleLogout = async () => {
    try {
      setIsLoggingOut(true);
      clearAuthStorage();
      await signOut({ callbackUrl: "/" });
    } catch {
      router.push("/signin");
    } finally {
      setIsLoggingOut(false);
      setIsDropdownOpen(false);
    }
  };

  const profile = (authData as any)?.user?.profile;
  const firstName: string =
    profile?.first_name ?? authData?.user?.name?.split(" ")[0] ?? "";
  const lastName: string =
    profile?.last_name ?? authData?.user?.name?.split(" ").slice(-1)[0] ?? "";
  const initials =
    firstName && lastName
      ? `${firstName[0]}${lastName[0]}`.toUpperCase()
      : firstName
        ? firstName[0].toUpperCase()
        : "U";

  return (
    <>
     <Suspense fallback={null}>
  <UpgradeModalGate />
</Suspense>
      <nav className="bg-[#0e1617] border border-[#FFFFFF1A] rounded-[24px] px-6 py-4 mb-6">
        <div className="flex items-center justify-between">
          {/* Left Side - Page Title */}
          <div className="flex items-center gap-3">
            <div className="flex-shrink-0">{pageIcon}</div>
            <h1 className="text-white text-xl lg:text-2xl font-mona-sans font-bold">
              {pageTitle}
            </h1>
          </div>

          {/* Right Side - Actions */}
          <div className="flex items-center gap-3 lg:gap-4">
            {/* Custom action slot */}
            {actionSlot && <div className="hidden sm:block">{actionSlot}</div>}

            {subcriptionPlanName?.toLowerCase() == "basic" && (
              <>
                <button onClick={openUpgradeModal} className="">
                  <UpgradeButton />
                </button>

                <div className="">
                  <BasicPlanIcon />
                </div>
              </>
            )}

            {/* Notification */}
            <div
              className="relative"
              ref={notifRef}
              onMouseEnter={() => setIsNotifOpen(true)}
              onMouseLeave={() => setIsNotifOpen(false)}
            >
              <button
                onClick={() => router.push("/dashboard/notifications")}
                className="flex-shrink-0 hover:opacity-80 transition-opacity"
              >
                <NotificationIcon />
              </button>

              {/* Notification Modal */}
              {isNotifOpen && (
                <div
                  className="absolute right-0 mt-3 w-[359px] rounded-[24px] z-50 overflow-hidden"
                  style={{
                    background:
                      "linear-gradient(0deg, #313035, #313035), linear-gradient(81.09deg, #222126 13.55%, #111116 187.95%)",
                    boxShadow: "0 8px 32px rgba(0,0,0,0.4)",
                  }}
                >
                  {/* Header */}
                  <div className="flex items-center justify-between px-5 pt-5 pb-3">
                    <h3 className="text-white font-mona-sans font-bold text-lg">
                      Notification
                    </h3>
                    <button className="text-[#A2CE3A] font-mona-sans text-sm hover:opacity-80 transition-opacity">
                      Mark as read
                    </button>
                  </div>

                  {/* Notification List */}
                  <div className="overflow-y-auto max-h-[490px] px-3 pb-4 flex flex-col gap-1">
                    {notificationItems.map((item, i) => (
                      <div
                        key={i}
                        className="flex items-start gap-3 px-3 py-3 rounded-xl hover:bg-white/5 transition-colors cursor-pointer"
                      >
                        <div className="flex-shrink-0">{item.icon}</div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1.5 mb-0.5">
                            <span className="text-white font-mona-sans font-semibold text-sm">
                              {item.title}
                            </span>
                            {item.unread && (
                              <span className="w-1.5 h-1.5 rounded-full bg-[#A2CE3A] flex-shrink-0" />
                            )}
                          </div>
                          <p className="text-[#9CA3AF] font-mona-sans text-xs leading-relaxed line-clamp-2">
                            {item.description}
                          </p>
                        </div>
                        <span className="text-[#6B7280] font-mona-sans text-xs flex-shrink-0">
                          {item.time}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Profile Dropdown */}
            <div className="relative">
              <button
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="flex items-center gap-2 hover:opacity-80 transition-opacity"
              >
                <div className="w-12 h-12 rounded-full overflow-hidden bg-gradient-to-br from-[#A2CE3A] to-[#156374] flex items-center justify-center flex-shrink-0">
                  {avatarUrl ? (
                    <img
                      src={avatarUrl}
                      alt="Profile"
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <span className="text-white font-mona-sans font-bold text-sm">
                      {initials}
                    </span>
                  )}
                </div>
                <div className="hidden lg:block">
                  <DropdownArrow />
                </div>
              </button>

              {/* Dropdown Menu */}
              {isDropdownOpen && (
                <div
                  className="absolute right-0 mt-2 w-48 rounded-lg shadow-lg z-50"
                  style={{
                    background: "#1563741A",
                    border: "0.5px solid #FFFFFF1A",
                  }}
                >
                  <button
                    onClick={handleLogout}
                    disabled={isLoggingOut}
                    className="w-full px-4 py-3 text-left text-sm font-medium text-red-400 hover:bg-white/5 transition-colors disabled:opacity-50 rounded-lg flex items-center gap-2"
                  >
                    <svg
                      width="16"
                      height="16"
                      viewBox="0 0 16 16"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                    >
                      <path
                        d="M6 14H3C2.44772 14 2 13.5523 2 13V3C2 2.44772 2.44772 2 3 2H6M11 11L14 8M14 8L11 5M14 8H6"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                    {isLoggingOut ? "Logging out..." : "Logout"}
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </nav>
    </>
  );
}
